class Solution {
public:
    vector<int> minimumFlips(int n, vector<vector<int>>& edges, string start, string target) {
        vector<vector<pair<int,int>>> adj(n);
        for (int i = 0; i < (int)edges.size(); ++i) {
            int u = edges[i][0], v = edges[i][1];
            adj[u].push_back(make_pair(v, i));
            adj[v].push_back(make_pair(u, i));
        }
        vector<int> parent(n, -1), edgeId(n, -1), order(1, 0), mismatch(n);
        for (int i = 0; i < n; ++i) mismatch[i] = (start[i] != target[i]);
        for (int i = 0; i < (int)order.size(); ++i) {
            int u = order[i];
            for (auto e : adj[u]) if (e.first != parent[u]) {
                parent[e.first] = u;
                edgeId[e.first] = e.second;
                order.push_back(e.first);
            }
        }
        vector<int> result;
        for (int i = n - 1; i > 0; --i) {
            int u = order[i];
            if (mismatch[u]) {
                result.push_back(edgeId[u]);
                mismatch[parent[u]] ^= 1;
            }
        }
        if (mismatch[0]) return vector<int>(1, -1);
        sort(result.begin(), result.end());
        return result;
    }
};
